Param(    [Parameter(Mandatory=$true)] [string]$stackName)$stackNameLower = $stackName.ToLower() echo "Deleting the ${stackName} stack"aws s3api list-buckets --query "Buckets[?starts_with(Name, ``${stackNameLower}-admin-assets``) == ``true``].[Name]" --output text | %{aws s3 rb s3://$_ --force | Out-Null}aws s3api list-buckets --query "Buckets[?starts_with(Name, ``${stackNameLower}-admin-uploads``) == ``true``].[Name]" --output text | %{aws s3 rb s3://$_ --force | Out-Null}aws cloudformation delete-stack --stack-name "${stackName}"echo "${stackName} stack deleted!"